package ro.leo.visual;
import ro.leo.i18n.L;
import android.content.*;import android.os.Bundle;import android.graphics.*;import android.view.*;import android.widget.*;import java.util.*;
public final class WallpaperActivity extends LeoActivity {
    private int stock=-1,themePreview=-1;
    protected void onCreate(Bundle state){super.onCreate(state);show();}
    private void show(){stock=-1;themePreview=-1;list(L.t("Fundaluri și teme"),Arrays.asList(L.t("Colecții vizuale complete"),L.t("Fundaluri incluse"),L.t("Imagine din Galerie"),L.t("Elimină imaginea de fundal"),L.t("Teme avansate")),0,new Choice(){public void pick(int at){if(at==0)startActivity(new Intent(WallpaperActivity.this,ThemePacksActivity.class));else if(at==1)preview(0);else if(at==2)startActivity(new Intent(WallpaperActivity.this,GalleryActivity.class).putExtra("wallpaper",true));else if(at==4)themes();else options(L.t("Elimini fundalul?"),new String[]{L.t("Păstrează"),L.t("Elimină")},new Choice(){public void pick(int yes){if(yes==1){if(Appearance.wallpaper(WallpaperActivity.this).exists()&&!Appearance.wallpaper(WallpaperActivity.this).delete())notice(L.t("Nu poate fi eliminat"));else notice(L.t("Fundal eliminat"));}}});}},"",null);}
    private void themes(){stock=-1;themePreview=-1;list(L.t("Teme avansate"),Arrays.asList(Appearance.THEMES),0,new Choice(){public void pick(int at){previewTheme(at);}},"",null);back=new Runnable(){public void run(){show();}};}
    private void preview(int which){stock=Math.floorMod(which,StockWallpapers.NAMES.length);begin(StockWallpapers.NAMES[stock]);root.addView(new View(this){protected void onDraw(Canvas c){StockWallpapers.draw(c,stock,getWidth(),getHeight());}},new LinearLayout.LayoutParams(-1,0,1));left=new Runnable(){public void run(){try{StockWallpapers.apply(WallpaperActivity.this,stock);notice(L.t("Fundal aplicat pe Home și ecranul blocat"));}catch(java.io.IOException e){notice(L.t("Fundalul nu a putut fi salvat"));}}};back=new Runnable(){public void run(){show();}};footer(L.t("Aplică"),"← / → model",L.t("Înapoi"));}
    private void previewTheme(int which){stock=-1;themePreview=Math.floorMod(which,Appearance.THEMES.length);begin(L.t("Previzualizare temă"));final Appearance.Palette sample=new Appearance.Palette(Appearance.COLORS[themePreview]);root.addView(new View(this){final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);protected void onDraw(Canvas c){c.save();c.scale(getWidth()/240f,getHeight()/218f);p.setShader(null);p.setColor(sample.background);c.drawRect(0,0,240,218,p);p.setShader(null);p.setColor(sample.bar);c.drawRoundRect(12,12,228,62,3,3,p);p.setColor(Color.WHITE);p.setTextSize(18);c.drawText(Appearance.THEMES[themePreview],22,43,p);p.setColor(sample.card);c.drawRoundRect(12,77,228,119,3,3,p);p.setColor(Color.WHITE);p.setTextSize(16);c.drawText(L.t("Mesaje · Contacte"),23,104,p);p.setColor(sample.selection);c.drawRoundRect(12,130,228,174,3,3,p);p.setColor(sample.ink);c.drawText(L.t("Selecție din taste"),23,158,p);p.setColor(sample.bar);c.drawRect(0,187,240,218,p);p.setColor(Color.WHITE);p.setTextSize(12);c.drawText(L.t("← / → alte teme · OK aplică"),23,202,p);c.restore();}},new LinearLayout.LayoutParams(-1,0,1));left=new Runnable(){public void run(){getSharedPreferences("appearance",0).edit().putInt("theme",themePreview).putBoolean("warm",themePreview==1).apply();show();notice(L.t("Tema aplicată"));}};back=new Runnable(){public void run(){show();}};footer(L.t("Aplică"),L.t("← / → temă"),L.t("Anulează"));}
    public boolean onKeyDown(int key,KeyEvent e){if(themePreview>=0){if(key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_DPAD_RIGHT){previewTheme(themePreview+(key==KeyEvent.KEYCODE_DPAD_LEFT?-1:1));return true;}if(key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER){if(e.getRepeatCount()==0)left.run();return true;}}if(stock>=0){if(key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_DPAD_RIGHT){preview(stock+(key==KeyEvent.KEYCODE_DPAD_LEFT?-1:1));return true;}if(key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER){if(e.getRepeatCount()==0&&left!=null)left.run();return true;}}return super.onKeyDown(key,e);}
}
